    dp[n + 1] = 1;
    pdp[n] = 1;
    pdp[n + 1] = 1;

    for (int i = n - 1; i >= 1; --i) {
        dp[i] = pdp[i + 1];
        pdp[i] = (dp[i] + pdp[i + 2]) % MOD;
    }

    int64 ans = dp[1];
    ans = ans * mod_pow(mod_pow(2, MOD - 2), n) % MOD;

    cout << ans << '\n';
    return 0;
